defprotocol Sized do
  @doc "返回数据大小"
  def size(data)
end

defimpl Sized, for: List do
  def size(list), do: length(list)
end

defimpl Sized, for: Map do
  def size(map), do: map_size(map)
end

defimpl Sized, for: BitString do
  def size(s), do: byte_size(s)
end

IO.inspect(Sized.size([1, 2, 3]))
IO.inspect(Sized.size(%{a: 1}))
IO.inspect(Sized.size("hello"))

defmodule Shapes do
  @type id :: pos_integer()
  @type point :: {number(), number()}
  @type shape :: {:circle, point(), number()} | {:rect, point(), point()}

  @spec area(shape()) :: float()
  def area({:circle, _center, r}), do: :math.pi() * r * r
  def area({:rect, {x1, y1}, {x2, y2}}), do: abs(x2 - x1) * abs(y2 - y1)

  @spec find([shape()], id()) :: {:ok, shape()} | :error
  def find(_shapes, _id), do: :error
end

IO.inspect(Shapes.area({:rect, {0, 0}, {3, 4}}))
IO.inspect(Shapes.find([], 1))

