defmodule Counter do
  use GenServer

  def start_link(init), do: GenServer.start_link(__MODULE__, init, name: __MODULE__)
  def incr, do: GenServer.cast(__MODULE__, :incr)
  def value, do: GenServer.call(__MODULE__, :value)

  @impl true
  def init(n), do: {:ok, n}

  @impl true
  def handle_cast(:incr, n), do: {:noreply, n + 1}

  @impl true
  def handle_call(:value, _from, n), do: {:reply, n, n}
end

{:ok, _pid} = Counter.start_link(0)
Counter.incr()
Counter.incr()
IO.inspect(Counter.value(), label: "计数")

GenServer.stop(Counter)
{:ok, _sup} = Supervisor.start_link([{Counter, 10}], strategy: :one_for_one)
IO.inspect(Counter.value(), label: "监督树下")
